/**
 * Stage 14 on the screen: the TensorRT compile banner + receipt, and the Decode / GPU / Encode queue row.
 *
 * `stage14.fixture.json` is generated by the BACKEND (gen-stage14-fixture.py): `predictor.warmup_session` driving a
 * stub ORT session through roop/pipeline_status.py, a real PipelineMonitor feeding roop/terminal_dashboard.py, and
 * the console text the backend itself painted. What is checked is the claim the feature makes - the React screen says
 * what the terminal says - and the path a browser takes (status snapshot -> pipelineStatus.js -> CompileBanner).
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

globalThis.window = globalThis;
// framer-motion's projection node attaches a resize listener to `window` even in a server render.
globalThis.addEventListener ??= () => {};
globalThis.removeEventListener ??= () => {};

const here = dirname(fileURLToPath(import.meta.url));
const fx = JSON.parse(readFileSync(join(here, 'stage14.fixture.json'), 'utf8'));

const React = (await import('react')).default;
const { renderToStaticMarkup } = await import('react-dom/server');
const M = await import('../src/components/faceswap/dashboardModel.js');
const { ConsoleMirrorView } = await import('../src/components/faceswap/ConsoleMirror.jsx');
const PS = await import('../src/pipelineStatus.js');
const { default: CompileBanner } = await import('../src/components/CompileBanner.jsx');
const { receiptText } = PS;

let failures = 0;
const ok = (name, cond, detail = '') => {
  if (cond) { console.log(`  PASS  ${name}`); return; }
  failures += 1;
  console.log(`  FAIL  ${name}${detail ? `\n          ${detail}` : ''}`);
};
const html = (el) => renderToStaticMarkup(el).replace(/<!-- -->/g, '');
const text = (h) => h.replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;/g, "'").replace(/\s+/g, ' ');

// ── the queue row: the same words as the console line ─────────────────────────
const dashWith = (queues) => ({
  schema: 1, active: true, mode: 'live', updated_at: 1,
  job: { mode: 'video', label: 'clip.mp4' },
  stages: { S3: { id: 'S3', name: 'Swap', title: 'Main swap', state: 'RUNNING', pct: 10, done: 10, total: 100, unit: 'frames', elapsed_s: 1, rate: 5, eta_s: 10, eta_at: 2, paused: false, detail: {} } },
  telemetry: { latency_ms: {}, bottleneck: null, frames: 10, hit_rates: {}, queues },
});

for (const [key, label] of [['gpu_bound', 'GPU-bound'], ['decode_bound', 'decode-bound'], ['encode_bound', 'encode-bound'], ['chunks', 'stabilization chunks']]) {
  const q = fx.queues[key];
  const dash = dashWith(q);
  const consoleLine = fx.console[key];
  const cells = M.queueCells(dash);
  const body = cells.map((c) => `${c.label}: ${c.value}`).join(' | ');
  const bound = M.queueBound(dash).text;
  ok(`${label}: the React cells read as the console line`, consoleLine.startsWith(body) && consoleLine.endsWith(bound),
    `${consoleLine}  vs  ${body} ${bound}`);
  const screen = text(html(React.createElement(ConsoleMirrorView, { dash })));
  ok(`${label}: and appear on the screen`, cells.every((c) => screen.includes(`${c.label} ${c.value}`)) && screen.includes(bound), screen.slice(0, 400));
}

{
  const cells = M.queueCells(dashWith(fx.queues.gpu_bound));
  ok('GPU fill is busy / workers, decode and encode are depth / capacity',
    cells.map((c) => c.fill).join() === '1,1,0.25', cells.map((c) => c.fill).join());
  const chunk = M.queueCells(dashWith(fx.queues.chunks));
  ok('a path that cannot count its workers has no GPU cell (a 0 would read as idle)', chunk.length === 2 && chunk.every((c) => c.key !== 'gpu'));
  ok('...and names its unit', chunk[0].unit === 'chunks');
  ok('verdict tone: GPU-bound is the healthy shape, the others warn',
    M.queueBound(dashWith(fx.queues.gpu_bound)).tone === 'ok' && M.queueBound(dashWith(fx.queues.decode_bound)).tone === 'warn'
    && M.queueBound(dashWith(fx.queues.encode_bound)).tone === 'warn');
  ok('no sampled window yet -> "measuring", not a verdict', M.queueBound(dashWith({ ...fx.queues.gpu_bound, bound: null })).text === '[bound: measuring]');
  ok('no queues at all -> no row, no crash', M.queueCells(dashWith(null)).length === 0
    && !html(React.createElement(ConsoleMirrorView, { dash: dashWith(null) })).includes('console-queues'));
  const zero = M.queueCells(dashWith({ ...fx.queues.gpu_bound, decode: { depth: 3, cap: 0 } }));
  ok('a zero capacity does not divide', zero[0].fill === null);
}

// ── the compile banner ───────────────────────────────────────────────────────
{
  const rows = PS.activeStages(fx.compiling);
  ok('the live compile row carries workspace + cache path from the session options',
    rows.length === 1 && rows[0].model === 'gpen_256' && rows[0].precision === 'FP16' && rows[0].workspaceMb === 2048 && rows[0].cachePath === fx.cache_path,
    JSON.stringify(rows));
  ok('the backend labels the stage TRT_COMPILE', fx.compiling.active[0].stage === 'TRT_COMPILE');
  ok('a row without them is null, never a guess', PS.activeStages({ active: [{ kind: 'STAGE_COMPILING_TRT', model: 'm' }] })[0].workspaceMb === null);

  PS.resetPipelineStatus();
  PS.applySnapshot(fx.compiling);
  const banner = text(html(React.createElement(CompileBanner)));
  ok('the banner names model, precision badge, workspace and cache directory',
    banner.includes('Compiling TensorRT engine') && banner.includes('gpen_256') && banner.includes('FP16')
    && banner.includes('workspace 2048 MB') && banner.includes(`cache ${fx.cache_path}`), banner);
  ok('...as a status, never a modal', html(React.createElement(CompileBanner)).includes('role="status"'));

  const miss = PS.lastCompile(fx.after_miss);
  const hit = PS.lastCompile(fx.after_hit);
  ok('a build that wrote a plan is a cache MISS with its time', miss.cacheHit === false && /^TRT cache miss · built in \d+s$/.test(receiptText(miss)), receiptText(miss));
  ok('a build that wrote nothing is a cache HIT, sub-second precision kept', hit.cacheHit === true && /^TRT cache hit · \d+\.\d\ds$/.test(receiptText(hit)), receiptText(hit));
  ok('the terminal receipt says MISS / HIT for the same two builds',
    fx.miss_receipt.startsWith('[TRT CACHE MISS: built in') && fx.hit_receipt.startsWith('[TRT CACHE HIT:'));
  ok('a failed build is a failed receipt, not a hit', receiptText({ ok: false, elapsedS: 3, cacheHit: null }).startsWith('Engine build failed'));
  ok('an uninspectable cache says "ready", not hit or miss', receiptText({ ok: true, elapsedS: 3, cacheHit: null }).startsWith('Engine ready'));
  ok('a CUDA / CPU warm-up is not an engine build: no receipt', PS.lastCompile(fx.after_cuda) === null);
  ok('no snapshot, no receipt', PS.lastCompile(undefined) === null && PS.lastCompile({}) === null);

  PS.resetPipelineStatus();
  PS.applySnapshot(fx.after_miss);
  ok('idle after a build the page did not watch: no banner (the backend keeps its last compile all session)',
    !html(React.createElement(CompileBanner)).includes('compile-banner'));
  PS.resetPipelineStatus();
}

console.log(failures === 0 ? '\nstage 14: all checks passed' : `\nstage 14: ${failures} FAILED`);
globalThis.__RENDER_CHECK_FAILURES__ = failures;
